#!/usr/bin/env python3\n\"\"\"\nFocused Debug for TradingRules Direction Logic\n\nThis script will test the exact values being passed to _determine_trade_direction\nto identify why strong signals (12.0+) are returning NEUTRAL.\n\"\"\"\n\nimport asyncio\nimport sys\nimport os\nimport pandas as pd\nfrom datetime import datetime\n\n# Add app to path\nsys.path.append('/app')\nsys.path.append('.')\n\nasync def debug_trading_rules():\n    \"\"\"Debug the exact TradingRules direction determination.\"\"\"\n    \n    try:\n        # Import modules\n        from app.logic.rules import TradingRules\n        from app.services.rate_limited_data_collector import rate_limited_collector\n        \n        print(\"🔍 Testing TradingRules Direction Logic...\")\n        \n        # Test with pairs that showed strong signals\n        test_pairs = [\"ETHUSDT\", \"SOLUSDT\"]\n        \n        for symbol in test_pairs:\n            print(f\"\\n📊 Testing {symbol}...\")\n            \n            # Get market data for this pair\n            data = await rate_limited_collector.collect_multi_pair_data([symbol])\n            \n            if symbol not in data or not data[symbol]:\n                print(f\"❌ No data available for {symbol}\")\n                continue\n                \n            symbol_data = data[symbol]\n            \n            # Test TradingRules analysis directly\n            print(f\"🔬 Running TradingRules.analyze_symbol for {symbol}...\")\n            analysis = await TradingRules.analyze_symbol(symbol, symbol_data)\n            \n            print(f\"📈 Analysis Results for {symbol}:\")\n            print(f\"   Direction: {analysis.get('direction', 'N/A')}\")\n            print(f\"   Strength: {analysis.get('strength', 'N/A')}\")\n            print(f\"   Confluence Points: {analysis.get('confluence_points', 'N/A')}\")\n            \n            # If neutral, show detailed rejection reasons\n            if analysis.get('direction') == 'NEUTRAL':\n                print(f\"❌ NEUTRAL Direction - Rejection Details:\")\n                print(f\"   Reason: {analysis.get('reason', 'N/A')}\")\n                print(f\"   Rejection Reasons: {analysis.get('rejection_reasons', 'N/A')}\")\n                print(f\"   Long Signals: {analysis.get('long_signals', 'N/A')}\")\n                print(f\"   Short Signals: {analysis.get('short_signals', 'N/A')}\")\n                print(f\"   Long Confluence: {analysis.get('long_confluence', 'N/A')}\")\n                print(f\"   Short Confluence: {analysis.get('short_confluence', 'N/A')}\")\n            \n            # Test trend alignment separately\n            trend_info = TradingRules._check_trend_alignment(symbol_data)\n            print(f\"📊 Trend Alignment for {symbol}:\")\n            print(f\"   Direction: {trend_info.get('direction', 'N/A')}\")\n            print(f\"   Aligned: {trend_info.get('aligned', 'N/A')}\")\n            print(f\"   Strength: {trend_info.get('strength', 'N/A')}\")\n            \n            # Test _determine_trade_direction directly with mock data\n            print(f\"🧪 Testing _determine_trade_direction directly...\")\n            trade_direction = TradingRules._determine_trade_direction(\n                symbol_data, \n                trend_info.get('direction', 'NEUTRAL'),\n                trend_info.get('strength', 50.0)\n            )\n            print(f\"📤 Direct Trade Direction Result:\")\n            print(f\"   Direction: {trade_direction.get('direction', 'N/A')}\")\n            print(f\"   Strength: {trade_direction.get('strength', 'N/A')}\")\n            print(f\"   Details: {trade_direction}\")\n            \n    except Exception as e:\n        print(f\"❌ Error in trading rules debug: {e}\")\n        import traceback\n        traceback.print_exc()\n\nif __name__ == \"__main__\":\n    asyncio.run(debug_trading_rules()) 